using DSAExperimentation.Algorithms.DynamicProgramming;
namespace DSAExperimentation.Tests.LeetCodeCoverage.BestTimeToBuyAndSellStockIV;
public sealed partial class BestTimeToBuyAndSellStockIVTests { [Theory] [InlineData(2,new[]{2,4,1},2)] [InlineData(2,new[]{3,2,6,5,0,3},7)] public void MaxProfit_Examples_ReturnsBestKTransactions(int k,int[] prices,int expected)=>Assert.Equal(expected,MaxProfit(k,prices)); private static int MaxProfit(int k,int[] prices){return Memoizer.Memoize<(int Day,int Holding,int Done),int>((0,0,0),Best);int Best((int Day,int Holding,int Done)s,Func<(int Day,int Holding,int Done),int> best){if(s.Day==prices.Length||s.Done==k)return 0;var skip=best((s.Day+1,s.Holding,s.Done));return s.Holding==1?Math.Max(skip,prices[s.Day]+best((s.Day+1,0,s.Done+1))):Math.Max(skip,-prices[s.Day]+best((s.Day+1,1,s.Done)));}} }
